# owner: platform
import unittest

from hourglass.timesheet import timesheet_lines
from hourglass.models import Shift, Span


def shift(worker, day, start, end):
    return Shift(worker, day, Span(start, end))


class TimesheetTests(unittest.TestCase):
    def test_busiest_first(self):
        lines = timesheet_lines([
            shift("Ana", "mon", 540, 600),
            shift("Ben", "mon", 540, 1020),
            shift("Ben", "tue", 540, 690)
        ])
        self.assertEqual(lines, [
            "Ben: 2 shifts, 10.5 hours",
            "Ana: 1 shifts, 1.0 hours"
        ])

    def test_one_decimal_place(self):
        lines = timesheet_lines(
            [shift("Ana", "mon", 0, 100)]
        )
        self.assertEqual(
            lines, ["Ana: 1 shifts, 1.7 hours"]
        )

    def test_ties_break_by_name(self):
        lines = timesheet_lines([
            shift("Zed", "mon", 0, 60),
            shift("Amy", "tue", 0, 60)
        ])
        self.assertTrue(lines[0].startswith("Amy"))

    def test_empty_list_raises(self):
        with self.assertRaises(ValueError):
            timesheet_lines([])

    def test_blank_worker_raises(self):
        for name in ("", "   "):
            with self.subTest(name=name):
                with self.assertRaises(ValueError):
                    timesheet_lines(
                        [shift(name, "mon", 0, 60)]
                    )
